// Сохранение «סוג מודעה» и «מיקום העסק בחו"ל» в черновике на сервере (#b93c54, specs/addbusiness-draft-save.md, раздел 3).
// ПРОД, ПИШУЩИЕ тесты (@data): создаётся реальный черновик «QA-TEST QA-AUTO …» под user и удаляется в afterEach.
// Блок записи: пропускаются только POST rest/v1/business (создание своего черновика), PATCH/DELETE business?id=eq.<свой id>
// и продление сессии (POST auth/v1/token); прочие не-GET (user_activity, Google Places и т. п.) — abort.
// Локальная копия мастера biz4sale:addBusinessDraft:* стирается при каждой загрузке документа (addInitScript),
// поэтому повторное открытие ?id= читает только сервер.
// Запуск только с QA_REAL_WRITE=1 (как addbusiness-photos-step).
// Используется и для #b30e4c (сохранение шагов у повторно открытого черновика): тело PATCH запоминается в ctl.patches.
import { expect, BrowserContext, Page, Request } from '@playwright/test';

export const LOAD = { timeout: 25_000 };
export const REAL_WRITE = process.env.QA_REAL_WRITE === '1';
export const SKIP_REASON =
  'Пишет на прод (черновик «QA-TEST» под user, удаляется в afterEach). Запуск только с QA_REAL_WRITE=1.';

