export const DESC_PH = 'תרשום את תיאור העסק שלך, חשוב מאוד יעזור לך למכור!';
export const PHONE_PH = 'טלפון ליצירת קשר*';
export const PRICE_PH = 'מחיר';
export const ABROAD_PH = 'מיקום העסק בחו"ל*';
export const ADDRESS = 'כתובת (רחוב ומספר בית)';
export const CITY_BUTTON = 'פתח רשימת ערים';
export const STEP2_MARK = 'משך פעילות העסק (שנים/חודשים)';
export const STEP4_HEADING = 'בחר חבילת פרסום';

export const HALLS = 'אולמות אירועים';
export const CAFES = 'בתי קפה ומסעדות';
