export const REGION = 'מרכז';

const SAFE = ['GET', 'HEAD', 'OPTIONS'];
const isBusiness = (url: string) => /\/rest\/v1\/business(\?|$)/.test(url);
const DRAFT_KEY = 'biz4sale:addBusinessDraft:';

export type Row = Record<string, any>;
export type Ctl = {
  title: string;
  draftId: string | null;
  postBody: Row | null;
  patches: { url: string; status: number; body: Row | null }[];
  /** Прочие не-GET (user_activity, Google Places…) — оборваны в браузере, до сервера не дошли; только для отладки. */
  blocked: string[];
  auth: { origin: string; apikey: string; authorization: string; profile: string } | null;
};

export function newTitle(tag: string, hash = 'b93c54') {
  return `QA-TEST QA-AUTO ${hash} ${tag} ${Date.now()}`;
}

/** Перехват записи + cookie «חיוניים בלבד», окно PWA снято, локальный черновик мастера стёрт на каждой загрузке. */
export async function prepare(context: BrowserContext, title: string): Promise<Ctl> {
  const ctl: Ctl = { title, draftId: null, postBody: null, patches: [], blocked: [], auth: null };

  await context.addInitScript((key) => {
    try {
      localStorage.setItem(
        'cookie-consent-v2',
        JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
      );
      localStorage.setItem('b4s_install_prompt_dismissed_at', String(Date.now()));
      for (const k of Object.keys(localStorage)) if (k.startsWith(key)) localStorage.removeItem(k);
    } catch {}
  }, DRAFT_KEY);

  await context.route('**/*', async (route) => {
    const req = route.request();
    const m = req.method();
    const url = req.url();
    const h = req.headers();
    if (isBusiness(url) && h['apikey'] && h['authorization']) {
      ctl.auth = {
        origin: new URL(url).origin,
        apikey: h['apikey'],
        authorization: h['authorization'],
        profile: h['accept-profile'] || h['content-profile'] || 'public',
      };
    }
    if (SAFE.includes(m) || (m === 'POST' && /\/auth\/v1\/token/.test(url))) return route.fallback();
    if (m === 'POST' && isBusiness(url) && !ctl.postBody) {
      let body = req.postDataJSON();
      if (Array.isArray(body)) body = body[0];
      ctl.postBody = body ?? {};
      return route.fallback();
    }
    if ((m === 'PATCH' || m === 'DELETE') && isBusiness(url) && ctl.draftId && url.includes(`id=eq.${ctl.draftId}`)) {
      return route.fallback();
    }
    ctl.blocked.push(`${m} ${url}`);
    return route.abort('blockedbyclient');
  });

  context.on('requestfinished', async (r: Request) => {
    if (r.method() === 'PATCH' && isBusiness(r.url())) {
      const res = await r.response();
      let body: Row | null = null;
      try {
        body = r.postDataJSON();
      } catch {}
      ctl.patches.push({ url: r.url(), status: res?.status() ?? 0, body });
    }
  });

  return ctl;
}

/** Расшифровка записи images «meta:business_fields:<base64 JSON>». */
export function decodeMeta(images: unknown): Row | null {
  if (!Array.isArray(images)) return null;
  const item = images.find((x) => typeof x === 'string' && x.startsWith('meta:business_fields:')) as string | undefined;
  if (!item) return null;
  return JSON.parse(Buffer.from(item.slice('meta:business_fields:'.length), 'base64').toString('utf8'));
}

export async function openNewWizard(page: Page) {
  page.on('dialog', (d) => d.accept().catch(() => {}));
  await page.goto('/addbusiness');
  await expect(page.getByRole('button', { name: NEXT }), 'шаг 1 мастера').toBeVisible(LOAD);
  await expect(page.getByPlaceholder(TITLE_PH), 'новая форма пустая').toHaveValue('');
}

export async function pick(page: Page, current: string, option: string) {
  await page.getByRole('combobox').filter({ hasText: current }).first().click();
  await page.getByRole('option', { name: option, exact: true }).click();
  await expect(page.getByRole('combobox').filter({ hasText: option }).first()).toBeVisible();
}

export async function fillCommon(page: Page, ctl: Ctl, category: string) {
  await page.getByPlaceholder(TITLE_PH).fill(ctl.title);
  await page.getByPlaceholder(DESC_PH).fill('QA-TEST QA-AUTO בדיקה אוטומטית — טיוטה נמחקת אוטומטית.');
  await page.getByPlaceholder(PHONE_PH).fill('0501234567');
  await page.getByPlaceholder(PRICE_PH).fill('100000');
  await pick(page, 'קטגוריה', category);
}

/** «שלב הבא» на шаге 1 → POST business 201, id черновика, шаг 2. */
export async function submitStep1(page: Page, ctl: Ctl) {
  const created = page.waitForResponse((r) => r.request().method() === 'POST' && isBusiness(r.url()), LOAD);
  await page.getByRole('button', { name: NEXT }).click();
  const res = await created;
  expect(res.status(), 'черновик создан — POST rest/v1/business 201').toBe(201);
  const json = await res.json();
  const row = Array.isArray(json) ? json[0] : json;
  ctl.draftId = row?.id ?? null;
  expect(ctl.draftId, 'id черновика из ответа POST').toBeTruthy();
  await expect(page.getByText(STEP2_MARK).first(), 'шаг 2 «נתונים נוספים»').toBeVisible(LOAD);
  await expect(page, 'URL остаётся /addbusiness').toHaveURL(/\/addbusiness(\?|$)/);
}

/** Строка черновика с сервера (чтение своей записи с той же сессией, что у сайта). */
export async function fetchRow(page: Page, ctl: Ctl): Promise<Row | null> {
  expect(ctl.auth, 'заголовки Supabase перехвачены').toBeTruthy();
  const res = await page.request.get(
    `${ctl.auth!.origin}/rest/v1/business?select=*&id=eq.${ctl.draftId}`,
    { headers: { apikey: ctl.auth!.apikey, authorization: ctl.auth!.authorization, 'accept-profile': ctl.auth!.profile } },
  );
  expect(res.status(), 'GET черновика').toBe(200);
  const rows = (await res.json()) as Row[];
  return rows[0] ?? null;
}

/** Открыть черновик заново по ?id= и дождаться заполнения формы (первые ~300 мс она пустая). */
export async function reopen(page: Page, ctl: Ctl) {
  await page.goto(`/addbusiness?id=${ctl.draftId}`);
  await waitFilled(page, ctl);
}

export async function waitFilled(page: Page, ctl: Ctl) {
  await expect(page.getByPlaceholder(TITLE_PH), 'форма заполнилась из черновика').toHaveValue(ctl.title, LOAD);
  expect(
    await page.evaluate((key) => Object.keys(localStorage).filter((k) => k.startsWith(key)), DRAFT_KEY),
    'локальной копии черновика не было — данные с сервера',
  ).toEqual([]);
}

export const combo = (page: Page, text: string) => page.getByRole('combobox').filter({ hasText: new RegExp(`^${text}$`) });
export const abroadField = (page: Page) => page.getByPlaceholder(ABROAD_PH, { exact: true });

export async function expectAbroadDraft(page: Page, place: string) {
  await expect(combo(page, HALLS), `категория «${HALLS}»`).toBeVisible();
  await expect(combo(page, PRIVATE), `«${PRIVATE}»`).toBeVisible();
  await expect(combo(page, ABROAD_TYPE), `סוג מודעה «${ABROAD_TYPE}»`).toBeVisible();
  await expect(abroadField(page), 'поле «מיקום העסק בחו"ל*» со значением').toHaveValue(place);
  await expect(page.getByRole('button', { name: CITY_BUTTON }), `нет «${CITY_BUTTON}»`).toHaveCount(0);
  await expect(page.getByRole('combobox', { name: ADDRESS }), `нет «${ADDRESS}»`).toHaveCount(0);
  await expect(combo(page, 'אזור'), 'нет списка «אזור»').toHaveCount(0);
}

/**
 * Очистка: /mybusinesses → карточка с точным названием → корзина → подтверждение → DELETE business?id=eq.<id> 2xx;
 * если UI не сработал — DELETE через API тем же id. В конце сервер подтверждает: записи нет.
 */
export async function cleanup(page: Page, ctl: Ctl): Promise<string[]> {
  const log: string[] = [];
  if (!ctl.draftId) return log;
  const id = ctl.draftId;
  try {
    await page.goto('/mybusinesses');
    const card = page
      .locator('div')
      .filter({ hasText: ctl.title })
      .filter({ has: page.getByRole('button', { name: 'עריכה' }) })
      .last();
    await expect(card).toBeVisible(LOAD);
    const deleted = page.waitForResponse(
      (r) => r.request().method() === 'DELETE' && isBusiness(r.url()) && r.url().includes(id),
      LOAD,
    );
    await card.getByRole('button').filter({ hasNotText: /\S/ }).last().click();
    const confirm = page
      .getByRole('alertdialog')
      .or(page.getByRole('dialog'))
      .getByRole('button', { name: /מחק|מחיקה|אישור|כן/ })
      .first();
    await Promise.race([deleted, confirm.waitFor({ timeout: LOAD.timeout }).then(() => confirm.click())]).catch(() => {});
    const res = await deleted;
    log.push(`UI DELETE ${id} → ${res.status()}`);
    await expect(page.getByText(ctl.title), 'карточки черновика больше нет').toHaveCount(0, LOAD);
  } catch (e) {
    log.push(`UI delete failed: ${(e as Error).message.split('\n')[0]}`);
    if (ctl.auth) {
      const res = await page.request.delete(`${ctl.auth.origin}/rest/v1/business?id=eq.${id}`, {
        headers: { apikey: ctl.auth.apikey, authorization: ctl.auth.authorization, 'content-profile': ctl.auth.profile },
      });
      log.push(`API DELETE ${id} → ${res.status()}`);
    }
  }
  const left = await fetchRow(page, ctl);
  expect(left, `черновик ${id} удалён на сервере — если нет, удалить вручную`).toBeNull();
  ctl.draftId = null;
  return log;
}
